\set ON_ERROR_STOP on
BEGIN READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL statement_timeout='10s';
SELECT 'SESSION|'||CASE WHEN current_setting('transaction_read_only')='on' AND session_user='firmova_app_runtime' AND current_user='firmova_app_runtime' AND EXISTS(SELECT FROM pg_stat_ssl WHERE pid=pg_backend_pid() AND ssl) THEN 'PASS' ELSE 'BLOCKED' END;
SELECT 'GUARD|'||e.name||'|'||CASE WHEN t.oid IS NULL THEN 'MISSING' WHEN t.tgenabled NOT IN ('O','A') OR t.tgtype<>e.kind OR t.tgqual IS NOT NULL OR t.tgnargs<>0 OR t.tgfoid IS DISTINCT FROM to_regprocedure('public.firmova_guard_primary_company()') OR (e.kind=27 AND t.tgattr::text IS DISTINCT FROM (SELECT attnum::text FROM pg_attribute WHERE attrelid=t.tgrelid AND attname='Id' AND NOT attisdropped)) OR NOT p.prosecdef OR NOT coalesce(p.proconfig @> ARRAY['search_path=pg_catalog, pg_temp'],false) OR md5(replace(p.prosrc,chr(13),''))<>:'expected_body_md5' THEN 'BLOCKED' ELSE 'PASS' END FROM (VALUES ('firmova_guard_primary_company_row',27),('firmova_guard_primary_company_truncate',34)) e(name,kind) LEFT JOIN pg_trigger t ON t.tgrelid=to_regclass('public."Firmalar"') AND t.tgname=e.name AND NOT t.tgisinternal LEFT JOIN pg_proc p ON p.oid=t.tgfoid ORDER BY e.name;
SELECT 'RUNTIME_DELETE_FIRMA|'||has_table_privilege('firmova_app_runtime','public."Firmalar"','DELETE')::text;
SELECT 'RUNTIME_READ_MAPPING|'||(coalesce(has_column_privilege('firmova_app_runtime',to_regclass('public.firmova_company_deletion_owner'),'singleton','SELECT'),false) AND coalesce(has_column_privilege('firmova_app_runtime',to_regclass('public.firmova_company_deletion_owner'),'user_id','SELECT'),false))::text;
SELECT 'DOCUMENT_FILE_GATES|'||CASE WHEN count(*)=6 AND to_regprocedure('public.firmova_lock_company_deletion_documents()') IS NULL THEN 'PASS' ELSE 'BLOCKED' END FROM pg_trigger t JOIN pg_proc p ON p.oid=t.tgfoid WHERE t.tgname='firmova_document_file_gate' AND NOT t.tgisinternal AND t.tgenabled IN('O','A') AND t.tgtype=31 AND t.tgqual IS NULL AND t.tgnargs=0 AND p.oid=to_regprocedure('public.firmova_guard_document_file()') AND p.prosecdef AND p.proconfig=ARRAY['search_path=pg_catalog, pg_temp'] AND NOT has_function_privilege('firmova_app_runtime',p.oid,'EXECUTE') AND t.tgrelid IN(to_regclass('public."Firmalar"'),to_regclass('public."Cekler"'),to_regclass('public."EkDosyalar"'),to_regclass('public."CompanyStoredFiles"'),to_regclass('public."CompanyStoredFileReferences"'),to_regclass('public."CompanyFileCleanupJobs"'));
SELECT 'RUNTIME_ISOLATION|'||CASE WHEN NOT(rolsuper OR rolcreaterole OR rolbypassrls OR rolreplication) AND NOT has_parameter_privilege(oid,'session_replication_role','SET') AND NOT has_table_privilege(oid,'public."Firmalar"','TRIGGER,TRUNCATE') AND NOT has_column_privilege(oid,'public."Kullanicilar"','FirmaId','UPDATE') AND NOT coalesce(has_table_privilege(oid,to_regclass('public.firmova_company_deletion_owner'),'INSERT,UPDATE,DELETE,TRUNCATE,TRIGGER'),false) AND NOT coalesce(has_any_column_privilege(oid,to_regclass('public.firmova_company_deletion_owner'),'INSERT,UPDATE'),false) AND NOT EXISTS(SELECT FROM (SELECT datdba AS owner FROM pg_database WHERE datname=current_database() UNION SELECT nspowner FROM pg_namespace WHERE nspname='public' UNION SELECT relowner FROM pg_class WHERE oid IN(to_regclass('public."Firmalar"'),to_regclass('public.firmova_company_deletion_owner'),to_regclass('public.firmova_document_file_gates')) UNION SELECT proowner FROM pg_proc WHERE oid IN(to_regprocedure('public.firmova_guard_primary_company()'),to_regprocedure('public.firmova_guard_document_file()'),to_regprocedure('public.firmova_document_file_id(text)'))) owners WHERE pg_has_role('firmova_app_runtime',owners.owner,'MEMBER')) THEN 'PASS' ELSE 'BLOCKED' END FROM pg_roles WHERE rolname='firmova_app_runtime';
ROLLBACK;
